#!/usr/bin/env bash
set -euo pipefail

readonly SOURCE_DEST=/app/thermal_modes.rs
readonly BINARY_DEST=/app/thermal_modes
readonly INPUT_DIR=/app/thermal_problem/cases
readonly OUTPUT_DIR=/app/thermal_mode_results
readonly SCRIPT_DIR="$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)"
readonly EMBEDDED_SOURCE_SHA256='a9fc115163b217cfdf3a18949fdab3373231544bd83d8f1d96661271efb56eb8'
readonly EMBEDDED_SOURCE_GZIP_BASE64=''

if [ ! -d "$INPUT_DIR" ]; then
  printf 'oracle: missing input directory: %s\n' "$INPUT_DIR" >&2
  exit 2
fi
if ! command -v rustc >/dev/null 2>&1; then
  printf 'oracle: rustc is not available in PATH\n' >&2
  exit 2
fi

source_path=''
for candidate in \
  "$SCRIPT_DIR/thermal_modes.rs" \
  /solution/thermal_modes.rs \
  /workspace/solution/thermal_modes.rs; do
  if [ -r "$candidate" ]; then
    source_path="$candidate"
    break
  fi
done

cleanup_path=''
if [ -z "$source_path" ]; then
  source_path="$(mktemp /tmp/thermal_modes_oracle_XXXXXX.rs)"
  cleanup_path="$source_path"
  python3 -c 'import base64,gzip,hashlib,pathlib,sys; raw=gzip.decompress(base64.b64decode(sys.argv[1])); actual=hashlib.sha256(raw).hexdigest(); expected=sys.argv[3]; (actual == expected) or (_ for _ in ()).throw(SystemExit("oracle: embedded source checksum mismatch")); pathlib.Path(sys.argv[2]).write_bytes(raw)' \
    "$EMBEDDED_SOURCE_GZIP_BASE64" "$source_path" "$EMBEDDED_SOURCE_SHA256"
fi
trap 'if [ -n "$cleanup_path" ]; then rm -f -- "$cleanup_path"; fi' EXIT

actual_sha="$(sha256sum "$source_path" | awk '{print $1}')"
if [ "$actual_sha" != "$EMBEDDED_SOURCE_SHA256" ]; then
  printf 'oracle: source checksum mismatch: %s\n' "$source_path" >&2
  exit 2
fi

install -m 0644 "$source_path" "$SOURCE_DEST"
rustc --edition=2021 -O --crate-name thermal_modes "$SOURCE_DEST" -o "$BINARY_DEST"
chmod 0755 "$BINARY_DEST"
"$BINARY_DEST" --input-dir "$INPUT_DIR" --output-dir "$OUTPUT_DIR"
